contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // We test that for any non-empty _tos array, calling transfer either reverts or returns true.
    // The function takes parameters to pass into C.transfer and observes whether it reverted.
    function run(address from, address caddress, address[] calldata _tos, uint v) public payable {
        require(_tos.length > 0);
        bool reverted;
        bool ret;
        try c.transfer(from, caddress, _tos, v) returns (bool _r) {
            reverted = false;
            ret = _r;
        } catch {
            reverted = true;
            ret = false;
        }
        // General rule: for any inputs with non-empty _tos, if call did not revert then it must have returned true.
        assert(reverted || ret == true);
    }
    receive() external payable { }
}

